cypress_script:
describe('Multi-Level Navigation Menu', () => {
  it('should navigate to the Text Box page when the Text Box link is clicked', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a.router-link').contains('Text Box').click();
    cy.url().should('include', '/text-box');
  });

  it('should not navigate when a non-clickable item is clicked', () => {
    cy.visit('https://demoqa.com/menu');
    cy.get('a').contains('Main Item 1').click();
    cy.url().should('eq', 'https://demoqa.com/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-Level Navigation Menu', () => {
  test('should navigate to the Text Box page when the Text Box link is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('a.router-link:has-text("Text Box")');
    await expect(page).toHaveURL(/.*text-box/);
  });

  test('should not navigate when a non-clickable item is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/menu');
    await page.click('a:has-text("Main Item 1")');
    await expect(page).toHaveURL('https://demoqa.com/menu');
  });
});
